// Pick first row where Status is blank / READY / PENDING
// Works even if header has spaces or different casing.

const getRows = () => {
  // Most common n8n formats:
  if (Array.isArray($json)) return $json;
  if (Array.isArray($json.data)) return $json.data;

  // Sometimes Sheets node returns one row per item:
  // items are not available directly in Code node, but $input is.
  const inputItems = $input.all().map(i => i.json);
  if (Array.isArray(inputItems) && inputItems.length) return inputItems;

  return [];
};

const rows = getRows();

const clean = (v) => (v === undefined || v === null) ? "" : String(v).trim();

// Find a key in row that "looks like" Status even if header is messy
const findStatusValue = (row) => {
  const keys = Object.keys(row || {});
  const statusKey = keys.find(k => clean(k).toLowerCase().replace(/\s+/g,'') === "status");
  if (!statusKey) return "";
  return clean(row[statusKey]);
};

const isReady = (statusVal) => {
  const st = clean(statusVal).toUpperCase();
  return st === "" || st === "READY" || st === "PENDING";
};

const picked = rows.find(r => isReady(findStatusValue(r)));

if (!picked) {
  // Debug helper: show what status values exist in first 5 rows
  const sample = rows.slice(0, 5).map(r => ({
    day: r.Day ?? r.day ?? "",
    statusDetected: findStatusValue(r),
    keys: Object.keys(r)
  }));

  return [{
    json: {
      done: true,
      reason: "No READY/PENDING rows found",
      debug_sample: sample,
      total_rows_seen: rows.length
    }
  }];
}

return [{
  json: {
    done: false,
    planRow: picked,
    detected_status: findStatusValue(picked)
  }
}];

// Build Memory Context (from Google Sheets)
// ✅ Correctly reads ALL rows from nodes using $items()
// ✅ Supports Old + New sheet formats
// ✅ Safe when Log sheet is empty / not executed

const planRow = $node["Pick Next Unprocessed Row"].json.planRow;

const safe = (v) => (v === undefined || v === null) ? "" : String(v);
const norm = (s) => safe(s).trim();

// ---- Read ALL Memory_Style rows ----
const styleItems = (() => {
  try { return $items("Read Memory_Style (Sheets)"); } catch (e) { return []; }
})();
const styleRowsRaw = styleItems.map(i => i.json).filter(Boolean);

// ---- Read ALL Brand_Memory rows (Key/Value) ----
const kvItems = (() => {
  try { return $items("Read Brand_Memory (Sheets)"); } catch (e) { return []; }
})();
const kvRowsRaw = kvItems.map(i => i.json).filter(Boolean);
const memory_kv = {};
for (const r of kvRowsRaw) {
  const k = norm(r.Key ?? r.key ?? "");
  if (!k) continue;
  memory_kv[k] = safe(r.Value ?? r.value ?? "");
}


// ---- Read ALL Log rows (safe) ----
const logItems = (() => {
  try { return $items("Read Log (Sheets)"); } catch (e) { return []; }
})();
const logRowsAllRaw = logItems.map(i => i.json).filter(Boolean);

// Enabled handling (if Enabled column missing => true)
const styleEnabled = (r) => {
  const eRaw = r?.Enabled ?? r?.enabled ?? r?.ENABLED;
  if (eRaw === undefined || eRaw === null || norm(eRaw) === "") return true;
  const e = norm(eRaw).toLowerCase();
  return e === "true" || e === "yes" || e === "1";
};

// Extract Key/Value from many possible header shapes
const extractKV = (row) => {
  if (!row) return { k: "", v: "", enabled: true };

  const k =
    norm(row.Key ?? row.key ?? row.KEY ?? row["Key "] ?? row.A ?? row.a ?? row["Column 1"] ?? row["column 1"] ?? "");
  const v =
    norm(row.Value ?? row.value ?? row.VALUE ?? row["Value "] ?? row.B ?? row.b ?? row["Column 2"] ?? row["column 2"] ?? "");

  return { k, v, enabled: styleEnabled(row) };
};

// Build style map {KEY: [values]}
const style = {};
for (const r of (Array.isArray(styleRowsRaw) ? styleRowsRaw : [])) {
  const { k, v, enabled } = extractKV(r);
  if (!enabled) continue;
  if (!k || !v) continue;
  if (!style[k]) style[k] = [];
  style[k].push(v);
}

// Helpers
const getOne = (key, fallback = "") => (style[key]?.[0] ?? fallback);
const getMany = (...keys) => keys.flatMap(k => style[k] || []);

// Recent examples (safe if empty)
const N = 30;
const logRowsAll = Array.isArray(logRowsAllRaw) ? logRowsAllRaw : [];
const logRows = logRowsAll.length ? logRowsAll.slice(-N) : [];

// ---- Build last-7 performance summary (memory_kv_performance) ----
const last7 = logRowsAll.length ? logRowsAll.slice(-7) : [];

const pick = (row, keys=[]) => {
  for (const k of keys) {
    const v = row?.[k];
    if (v !== undefined && v !== null && String(v).trim() !== "") return String(v).trim();
  }
  return "";
};

// Try to pull hooks / titles from either new or old column names
const perf = last7.map(r => ({
  day: pick(r, ["day_number", "Day", "day"]),
  core_topic: pick(r, ["core_topic", "CoreTopic", "topic"]),
  x_open: pick(r, ["x_threads", "x_thread", "xThread", "x_post", "x"]),
  ig_hook: pick(r, ["instagram_reel_hook", "ig_reel_hook", "IGHook"]),
  yt_hook: pick(r, ["youtube_shorts_hook", "yt_short_hook", "youtube_short_hook"]),
  li_post_open: pick(r, ["linkedin_post", "li_post", "linkedin"]),
  reddit_title: pick(r, ["reddit_title"]),
  score: pick(r, ["score_score", "score", "Publish Score"])
})).filter(x => x.day || x.core_topic);

// Compact string summary for LLM consumption
const perf_summary_lines = perf.map(p => {
  const parts = [];
  if (p.day) parts.push(`Day ${p.day}`);
  if (p.core_topic) parts.push(p.core_topic);
  if (p.score) parts.push(`Score:${p.score}`);
  if (p.ig_hook) parts.push(`IG:${p.ig_hook.slice(0, 80)}`);
  if (p.yt_hook) parts.push(`YT:${p.yt_hook.slice(0, 80)}`);
  if (p.reddit_title) parts.push(`Reddit:${p.reddit_title.slice(0, 80)}`);
  return parts.join(" | ");
}).slice(-7);

// Lists for “avoid repeats”
const last7_hooks = {
  ig: perf.map(p => p.ig_hook).filter(Boolean).slice(-7),
  yt: perf.map(p => p.yt_hook).filter(Boolean).slice(-7),
  x: perf.map(p => p.x_open).filter(Boolean).slice(-7)
};

const memory_kv_performance = {
  last7_summary: perf_summary_lines.join("\n"),
  last7_hooks,
  note: "Avoid repeating hooks/openers from last7_hooks. Prefer new angle variations."
};


const examples = logRows.map(r => {
  const day = norm(r.day_number || r.Day || "");
  const topic = norm(r.core_topic || r.CoreTopic || r.topic || "");
  const blogTitle = norm(r.blogger_title || r.blogger_title || r.blogger_title || "");
  const igHook = norm(r.instagram_reel_hook || r.instagram_reel_hook || r.instagram_reel_hook || "");
  const blogUrl = norm(r.blog_url || r.blog_public_url || r.blog_image_url || "");
  return [day && `Day ${day}`, topic && `Topic: ${topic}`, blogTitle && `Blog: ${blogTitle}`, igHook && `IG Hook: ${igHook}`, blogUrl && `URL: ${blogUrl}`]
    .filter(Boolean).join(" — ");
}).filter(Boolean);

const recentTopics = logRows.map(r => norm(r.core_topic || r.CoreTopic || r.topic || "")).filter(Boolean).slice(-10);
const recentBlogTitles = logRows.map(r => norm(r.blog_title || r.BlogTitle || r.title || "")).filter(Boolean).slice(-10);

const memory_context = memory_kv;

return [{
  json: {
    planRow,
    memory_kv,
    memory_kv_performance,
    style,
    memory_context,
    memory_examples: examples,
    debug: {
      style_rows_count: styleRowsRaw.length,
      style_keys_found: Object.keys(style),
      style_sample_first3: styleRowsRaw.slice(0, 3),
    }
  }
}];

const planRow = $node["Build Memory Context (Code)"].json.planRow || {};

// ---- helpers ----
const isObj = (v) => typeof v === "object" && v !== null && !Array.isArray(v);

const deepMerge = (target, src) => {
  if (!isObj(src)) return target;
  for (const [k, v] of Object.entries(src)) {
    if (isObj(v) && isObj(target[k])) {
      target[k] = deepMerge(target[k], v);
    } else {
      target[k] = v;
    }
  }
  return target;
};

const pick = (obj, path, fallback = undefined) => {
  try {
    const out = path.split(".").reduce((o, k) => o?.[k], obj);
    return out === undefined ? fallback : out;
  } catch {
    return fallback;
  }
};

const asString = (v) => (typeof v === "string" ? v : "");
const asObject = (v) => (isObj(v) ? v : {});
const asArray = (v) => (Array.isArray(v) ? v : []);

// ---- IMPORTANT: Merge all incoming items (because Merge node outputs array of objects) ----
const merged = $input.all().reduce((acc, item) => {
  const obj = item.json;
  if (isObj(obj)) deepMerge(acc, obj);
  return acc;
}, {});

// ---- extract sections (based on your merged JSON keys) ----
const blog = asObject(pick(merged, "blog", {}));

const ytReel = asObject(pick(merged, "youtube_short_reel", {})); // has {reel, youtube_short}
const ytLong = asObject(pick(merged, "youtube_long", {}));       // is the video object

const igFb = asObject(pick(merged, "instagram_facebook_post", {})); // {instagram, facebook}
const igCarousel = asObject(pick(merged, "instagram_carousel", {})); // {cover, slides, caption, hashtags}

const liArticle = asObject(pick(merged, "linkedin_article", {})); // {title, subtitle, body, cta}
const liPost = pick(merged, "linkedin_post", "");                 // string

const pin = asObject(pick(merged, "pinterest", {}));              // {title, description, board, image_prompt}
const xth = asObject(pick(merged, "x_thread_tweet", {}));         // {thread, tweet}
const reddit = asObject(pick(merged, "reddit", {}));              // {subreddit_suggestions,...}

// ---- plan metadata ----
const day = planRow.Day || planRow.day_number || planRow.day || "";
const core_topic = planRow["Core Topic"] || planRow.core_topic || "";
const pillar = planRow.Pillar || planRow.pillar || "";

// ---- normalize into your pkg shape ----
const pkg = {
  meta: {
    run_date: new Date().toISOString().slice(0, 10),
    day_number: day,
    core_topic,
    pillar,
    checklist_today: planRow.ChecklistToday
      ? String(planRow.ChecklistToday).split(/\s*\|\s*/).filter(Boolean)
      : []
  },

  outputs: {
    blogger: {
      title: blog.title || "",
      slug: blog.slug || "",
      meta_description: blog.meta_description || "",
      keywords: asArray(blog.keywords),
      html: blog.html || "",
      hero_prompt: blog.hero_prompt || ""
    },

    youtube: {
      short: asObject(ytReel.youtube_short),
      long: ytLong // NOTE: your ytLong is already the video object, not {video:{}}
    },

    instagram: {
      reel: asObject(ytReel.reel),
      post: asObject(igFb.instagram),
      carousel: igCarousel
    },

    facebook: asObject(igFb.facebook),

    linkedin: {
      // liArticle is already {title, subtitle, body, cta} in your merged json
      article: liArticle,
      post: asString(liPost)
    },

    // pin is already the pin object in your merged json, not {pin:{}}
    pinterest: pin,

    x: {
      thread: asArray(xth.thread),
      tweet: asString(xth.tweet)
    },

    // reddit is already the reddit object in your merged json, not {reddit:{}}
    reddit: reddit
  },

  raw: merged
};

// Optional debug: helps you confirm collector sees all keys
return [{
  json: {
    planRow,
    pkg,
    debug: {
      merged_keys: Object.keys(merged),
      has: {
        blog: !!merged.blog,
        youtube_short_reel: !!merged.youtube_short_reel,
        youtube_long: !!merged.youtube_long,
        instagram_facebook_post: !!merged.instagram_facebook_post,
        instagram_carousel: !!merged.instagram_carousel,
        linkedin_article: !!merged.linkedin_article,
        linkedin_post: !!merged.linkedin_post,
        pinterest: !!merged.pinterest,
        x_thread_tweet: !!merged.x_thread_tweet,
        reddit: !!merged.reddit
      }
    }
  }
}];

const raw = $json.output ?? $json.text ?? $json;
const t = (raw===undefined||raw===null) ? "" : String(raw);
let obj=null;
try { obj = JSON.parse(t); } catch(e) {
  const m = t.match(/\{[\s\S]*\}$/m);
  if (m) { try { obj = JSON.parse(m[0]); } catch(e2) {} }
}
if (!obj) obj = {score:0,human_score:0,quality_score:0,seo_score:0,rewrite_needed:true,issues:["Score parse failed"],rewrite_instructions:"Rewrite more naturally."};
return [{json: obj}];

const raw = $json.output ?? $json.text ?? $json;
const t = (raw===undefined||raw===null) ? "" : String(raw);
let obj=null;
try { obj = JSON.parse(t); } catch(e) {
  const m = t.match(/\{[\s\S]*\}$/m);
  if (m) { try { obj = JSON.parse(m[0]); } catch(e2) {} }
}
if (!obj || !obj.outputs) obj = $node["Collector / Normalizer (Code)"].json.pkg;
return [{ json: { pkg: obj } }];

const raw =
  $json.output ??
  $json.text ??
  $json.message ??
  $json;

const t = (raw === undefined || raw === null) ? "" : String(raw).trim();

let obj = null;

// 1️⃣ Try direct parse
try {
  obj = JSON.parse(t);
} catch (e) {}

// 2️⃣ Try extracting first JSON object anywhere in text
if (!obj) {
  const m = t.match(/\{[\s\S]*?\}/);
  if (m) {
    try { obj = JSON.parse(m[0]); } catch (e2) {}
  }
}

// 3️⃣ Normalize + fail-safe
const fallback = {
  score: 0,
  human_score: 0,
  quality_score: 0,
  seo_score: 0,
  rewrite_needed: false,
  issues: ["Score parse failed"],
  rewrite_instructions: ""
};

if (!obj || typeof obj !== "object" || Array.isArray(obj)) {
  return [{ json: fallback }];
}

// 4️⃣ Ensure all required keys exist
const result = {
  score: Number(obj.score) || 0,
  human_score: Number(obj.human_score) || 0,
  quality_score: Number(obj.quality_score) || 0,
  seo_score: Number(obj.seo_score) || 0,
  rewrite_needed: Boolean(obj.rewrite_needed),
  issues: Array.isArray(obj.issues) ? obj.issues : [],
  rewrite_instructions: typeof obj.rewrite_instructions === "string" ? obj.rewrite_instructions : ""
};

return [{ json: result }];

// Pick Final PKG (Code)
// Goal:
// - Use rewritten pkg ONLY if rewrite actually happened
// - Otherwise keep original
// - Prefer re-score only if rewrite happened

const original = $node["Collector / Normalizer (Code)"].json;
const originalPkg = original.pkg;
const planRow = original.planRow;

// SAFE SOURCE OF TRUTH (always executed)
const score1 = $node["Parse Score JSON"].json;
const rewriteFlag = !!score1.rewrite_needed;

let finalPkg = originalPkg;
let bestScore = score1;

// Only touch rewrite branch outputs if rewrite was needed
if (rewriteFlag) {
  const rewrittenNode = $node["Parse Rewritten PKG"];
  const rescoreNode = $node["Parse Re-Score JSON"];

  if (rewrittenNode?.json?.pkg?.outputs) {
    finalPkg = rewrittenNode.json.pkg;
  }

  if (rescoreNode?.json?.score !== undefined) {
    bestScore = rescoreNode.json;
  }
}

return [{
  json: {
    planRow,
    pkg: finalPkg,
    score: bestScore,
    rewrite_used: rewriteFlag
  }
}];

// Build Email HTML (supports: Blog + IG Reel + YT Short + YT Long + LinkedIn + X + Pinterest + Reddit + Checklist)
// ✅ Pulls checklist from "Checklist Agent (LLM)"
// ✅ Uses public image URLs from "Build Public URLs (Code)" + optional images object
// ✅ Safe if any field missing (blank instead of crashing)

const planRow = $node["Pick Next Unprocessed Row"].json.planRow;
const pkg = $("Pick Final PKG (Code)").first().json.pkg;

// score can come from Pick Final PKG or Parse Score
const score =
  $node["Pick Final PKG (Code)"]?.json?.score ??
  $node["Parse Score JSON"]?.json ??
  {};

// ✅ Checklist JSON (strict schema from your Checklist Agent)
const checklist =
   $input.first().json.checklist??
  $node["Checklist Agent (LLM)"]?.json?.output ??
  {};

pkg.meta.checklist_today = JSON.stringify(checklist).replace(/\\n/g, '').replace(/\\r/g, '').replace(/\\/g, '');

const runDate = pkg?.meta?.run_date || new Date().toISOString().slice(0, 10);

const safe = (v) => (v === undefined || v === null) ? "" : String(v);
const esc = (s) => safe(s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");
const br = (s) => esc(s).replace(/\n/g, "<br/>");
const nonEmpty = (v) => safe(v).trim() !== "";

const dayNumber = safe(pkg?.meta?.day_number ?? planRow.Day ?? "");
const coreTopic = safe(pkg?.meta?.core_topic ?? planRow.CoreTopic ?? "");
const pillar = safe(pkg?.meta?.pillar ?? planRow.Pillar ?? "");

// --- Outputs (robust keys) ---
const igReel = pkg?.outputs?.instagram?.reel ?? pkg?.outputs?.reel ?? {};
const igPost = pkg?.outputs?.instagram?.post ?? pkg?.outputs?.instagram ?? {};

const ytShort =
  pkg?.outputs?.youtube_short ??
  pkg?.outputs?.youtube?.short ??
  pkg?.outputs?.youtube?.youtube_short ??
  {};

const ytLong =
  pkg?.outputs?.youtube_long ??
  pkg?.outputs?.youtube?.long ??
  pkg?.outputs?.youtube?.video ??
  pkg?.outputs?.youtube?.long_form ??
  {};

const liPost =
  pkg?.outputs?.linkedin_post?.post ??
  pkg?.outputs?.linkedin?.post ??
  pkg?.outputs?.linkedin_post ??
  "";

const liArticle =
  pkg?.outputs?.linkedin_article?.article ??
  pkg?.outputs?.linkedin?.article ??
  pkg?.outputs?.linkedin_article ??
  {};

const xThread =
  pkg?.outputs?.x?.thread ??
  pkg?.outputs?.x_thread?.thread ??
  pkg?.outputs?.x_thread ??
  pkg?.outputs?.x ??
  [];

const pinterest =
  pkg?.outputs?.pinterest?.pin ??
  pkg?.outputs?.pinterest ??
  {};

const reddit =
  pkg?.outputs?.reddit ??
  pkg?.outputs?.reddit_post ??
  pkg?.outputs?.community_post ??
  {};

// Blogger
const blogTitle = safe(pkg?.outputs?.blogger?.title ?? pkg?.outputs?.blog?.title ?? "");
const blogHtml = safe(pkg?.outputs?.blogger?.html ?? pkg?.outputs?.blog?.html ?? "");

// --- Helpers ---
const section = (title, innerHtml) => {
  if (!innerHtml || !safe(innerHtml).trim()) return "";
  return `
    <hr style="border:none;border-top:1px solid #eee;margin:18px 0;" />
    <h3 style="margin:0 0 10px 0;">${esc(title)}</h3>
    ${innerHtml}
  `;
};

const imgBlock = (label, url, maxWidth = "680px") => {
  if (!nonEmpty(url)) return "";
  return `
    <p style="margin:10px 0 14px 0;">
      <b>${esc(label)}:</b><br/>
      <a href="${esc(url)}">${esc(url)}</a><br/>
      <img src="${esc(url)}" style="width:100%;max-width:${maxWidth};border-radius:14px;margin:10px 0;" />
    </p>
  `;
};

const listOrText = (v) => {
  if (Array.isArray(v)) {
    const items = v.map(t => safe(t).trim()).filter(Boolean);
    if (!items.length) return "";
    return items.map(t => `• ${esc(t)}`).join("<br/>");
  }
  return br(v);
};

// ✅ Checklist rendering
const checklistPlatform = (name) => {
  const p = checklist?.platforms?.[name] || {};
  const t = (p.time_estimate_min === 0 || p.time_estimate_min) ? safe(p.time_estimate_min) : "";
  const steps = Array.isArray(p.checklist) ? p.checklist.filter(Boolean) : [];
  const stepsHtml = steps.length ? steps.map(s => `<li>${esc(s)}</li>`).join("") : `<li>SKIP (missing content)</li>`;
  return `
    <h4 style="margin:14px 0 6px 0;">${esc(name)}${t ? ` <span style="color:#666;font-weight:normal;">(${esc(t)} min)</span>` : ""}</h4>
    <ul style="margin:6px 0 0 18px;padding:0;">${stepsHtml}</ul>
  `;
};

const postingOrderHtml = (() => {
  const arr = Array.isArray(checklist?.posting_order) ? checklist.posting_order : [];
  if (!arr.length) return `<li>(not provided)</li>`;
  return arr.map((x, i) =>
    `<li><b>${esc(x?.platform)}</b>: ${esc(x?.reason)}</li>`
  ).join("");
})();

const globalChecksHtml = (() => {
  const arr = Array.isArray(checklist?.global_checks) ? checklist.global_checks : [];
  if (!arr.length) return `<li>(not provided)</li>`;
  return arr.map(x => `<li>${esc(x)}</li>`).join("");
})();

// --- Build Email HTML ---
const emailHtml = `
  <div style="font-family: Arial, sans-serif; line-height:1.5; color:#111;">
    <h2 style="margin:0 0 6px 0;">Daily Content Brief — Day ${esc(dayNumber)}</h2>
    <p style="margin:0 0 14px 0;">
      <b>Date:</b> ${esc(runDate)}<br/>
      <b>Core Topic:</b> ${esc(coreTopic)}<br/>
      <b>Pillar:</b> ${esc(pillar)}<br/>
      <b>Readiness Score:</b> ${esc(score.score ?? "")}
      ${nonEmpty(score.human_score) || nonEmpty(score.seo_score)
        ? `(Human: ${esc(score.human_score ?? "")}, SEO: ${esc(score.seo_score ?? "")})`
        : ""}
    </p>

    ${section("✅ Publishing Order", `
      <ol style="margin:6px 0 0 18px;padding:0;">${postingOrderHtml}</ol>
    `)}

    ${section("✅ Global Checks", `
      <ul style="margin:6px 0 0 18px;padding:0;">${globalChecksHtml}</ul>
    `)}

    ${section("✅ Platform Checklists", `
      ${checklistPlatform("Blog")}
      ${checklistPlatform("LinkedIn Post")}
      ${checklistPlatform("X Thread")}
      ${checklistPlatform("IG Reel")}
      ${checklistPlatform("IG Post")}
      ${checklistPlatform("IG Carousel")}
      ${checklistPlatform("YouTube Short")}
      ${checklistPlatform("YouTube Long")}
      ${checklistPlatform("Pinterest Pin")}
      ${checklistPlatform("Reddit")}
    `)}


    ${section("Instagram Reel", `
      ${nonEmpty(igReel.hook) ? `<p><b>Hook:</b> ${esc(igReel.hook)}</p>` : ""}
      ${nonEmpty(igReel.script) ? `<p><b>Script:</b><br/>${br(igReel.script)}</p>` : ""}
      ${nonEmpty(igReel.caption) ? `<p><b>Caption:</b><br/>${br(igReel.caption)}</p>` : ""}
      ${(Array.isArray(igReel.hashtags) && igReel.hashtags.length)
        ? `<p><b>Hashtags:</b> ${esc(igReel.hashtags.join(" "))}</p>` : ""}
    `)}

    ${section("YouTube Short", `
      ${nonEmpty(ytShort.title) ? `<p><b>Title:</b> ${esc(ytShort.title)}</p>` : ""}
      ${nonEmpty(ytShort.hook) ? `<p><b>Hook:</b> ${esc(ytShort.hook)}</p>` : ""}
      ${nonEmpty(ytShort.script) ? `<p><b>Script:</b><br/>${br(ytShort.script)}</p>` : ""}
      ${nonEmpty(ytShort.description) ? `<p><b>Description:</b><br/>${br(ytShort.description)}</p>` : ""}
      ${(Array.isArray(ytShort.tags) && ytShort.tags.length)
        ? `<p><b>Tags:</b> ${esc(ytShort.tags.join(", "))}</p>` : ""}
    `)}

    ${section("YouTube Long (optional)", `
      ${nonEmpty(ytLong.title) ? `<p><b>Title:</b> ${esc(ytLong.title)}</p>` : ""}
      ${nonEmpty(ytLong.hook) ? `<p><b>Hook:</b> ${esc(ytLong.hook)}</p>` : ""}
      ${nonEmpty(ytLong.outline) ? `<p><b>Outline:</b><br/>${br(ytLong.outline)}</p>` : ""}
      ${nonEmpty(ytLong.script) ? `<p><b>Script:</b><br/>${br(ytLong.script)}</p>` : ""}
