// Checklist Agent (Code) — FIXED
// Reads checklist JSON from the LLM node safely and outputs 2 text blocks.
// Works whether the LLM output is in `.json` OR `.json.output` OR `.json.text` (stringified JSON).

const safe = (v) => (v === undefined || v === null) ? "" : String(v);

