const raw = llm.output ?? llm.json ?? llm.text ?? llm;

// 2) Parse if string, else use object
let c = raw;
if (typeof raw === "string") {
  try {
    c = JSON.parse(raw);
  } catch (e) {
    // try to extract last JSON block
    const m = raw.match(/\{[\s\S]*\}$/m);
    if (m) {
      try { c = JSON.parse(m[0]); } catch (e2) { c = {}; }
    } else {
      c = {};
    }
  }
}

// 3) Build texts
const postingOrderText = (Array.isArray(c?.posting_order) ? c.posting_order : [])
  .map((x, i) => `${i + 1}. ${safe(x?.platform)} — ${safe(x?.reason)}`.trim())
  .filter(Boolean)
  .join("\n");

const globalChecksText = (Array.isArray(c?.global_checks) ? c.global_checks : [])
  .map(safe)
  .filter(Boolean)
  .join("\n");

return [{
   ...$json,
    postingOrderText,
    globalChecksText,
    checklist: c
}];

