// YouTube / Reel Output Validator
// Fails fast if format or quality drifts
// Assumes Structured Output Parser already ran

const data = $input.first().json.output;

const errors = [];
const warnings = [];

const wordCount = (s) => s.trim().split(/\s+/).filter(Boolean).length;

// ---------- REEL VALIDATION ----------
if (!data.reel) {
  errors.push("Missing reel object");
} else {
  const r = data.reel;

  // Hook: 5–15 words
  const hookWords = wordCount(r.hook || "");
  if (hookWords < 5 || hookWords > 15) {
    errors.push(`Reel hook must be 8–12 words (got ${hookWords})`);
  }

  // Script length: approx 60–80 sec (750–1100 chars)
  const scriptLen = (r.script_en || "").length;
  if (scriptLen < 650 || scriptLen > 1300) {
    warnings.push(`Reel script length looks off (${scriptLen} chars)`);
  }

