if (!article.subtitle) {
  errors.push("Missing article subtitle");
}

// ---- Body rules ----
if (!article.body) {
  errors.push("Missing article body");
} else {
  // Opening POV: first 3 lines should hook
  const firstLines = article.body.split("\n").slice(0, 3).join(" ");
  if (wordCount(firstLines) < 20) {
    warnings.push("Opening POV may be too weak or short");
  }

  // Paragraph structure
  if (!article.body.includes("\n\n")) {
    warnings.push("Body lacks paragraph breaks (LinkedIn readability risk)");
  }

  // Checklist / framework presence
  const checklistSignals = ["- ", "•", "1.", "2.", "3."];
  const hasChecklist = checklistSignals.some(s =>
    article.body.includes(s)
  );
  if (!hasChecklist) {
    warnings.push("No checklist or framework detected");
  }

  // Personal line heuristic
  const personalSignals = ["I use", "I’ve found", "I learned", "In my workflow"];
  const hasPersonal = personalSignals.some(s =>
    article.body.toLowerCase().includes(s.toLowerCase())
  );
  if (!hasPersonal) {
    warnings.push("No personal-style line detected");
  }
}

