    warnings.push("CTA may be missing today's CTA keyword");
  }
}

// ---- Emoji rules (opening) ----
const openingParagraph = article.body.split("\n\n")[0] || "";
if (/🚀|🔥|💥|✨/.test(openingParagraph)) {
  errors.push("No emojis allowed in opening paragraph");
}

