const h2Count = (html.match(/<h2\b/gi) || []).length;
const h3Count = (html.match(/<h3\b/gi) || []).length;
if (h2Count < 2) errors.push("Need at least 2 <h2> headings");
if (h3Count < 1) warnings.push("Consider adding at least 1 <h3> for scannability");

// Code blocks requirement
const codeBlocks = (html.match(/<pre><code>[\s\S]*?<\/code><\/pre>/gi) || []).length;
if (codeBlocks < 1) errors.push("Need at least 1 code block (<pre><code>...</code></pre>)");
if (codeBlocks > 2) warnings.push("You have >2 code blocks; spec says 1–2");

// FAQ requirement (3–5 Qs)
// Minimal heuristic: look for "FAQ" section + at least 3 question marks after it
/*if (!has(html, "FAQ")) errors.push("Missing FAQ section");
else {
  const faqIndex = lower(html).indexOf("faq");
  const faqTail = faqIndex >= 0 ? html.slice(faqIndex) : "";
  const qCount = (faqTail.match(/\?/g) || []).length;
  if (qCount < 3) errors.push("FAQ should include 3–5 questions (detected <3 question marks)");
  if (qCount > 8) warnings.push("FAQ might be too long (detected many question marks)");
}*/

// CTA paragraph at end
if (ctaLine && !lower(html).includes(lower(ctaLine))) {
  warnings.push("CTA line not found verbatim in html (ensure final CTA paragraph matches CTA Unifier)");
}
if (ctaKeyword && !lower(html).includes(lower(ctaKeyword))) {
  warnings.push("CTA keyword not found in html (ensure CTA keyword appears)");
}

// No external JS
if (has(html, "<script")) errors.push("No <script> allowed in Blogger HTML");

// Avoid heavy CSS (soft check)
const styleTags = (html.match(/<style\b/gi) || []).length;
if (styleTags > 0) warnings.push("Avoid <style> tag if possible (keep CSS light/inlined)");

// Mention handle + website (soft requirement — warn, not fail)
if (handle && !lower(html).includes(lower(handle))) {
  warnings.push(`Handle not mentioned in html: ${handle}`);
}
if (website && !lower(html).includes(lower(website))) {
  warnings.push(`Website not mentioned in html: ${website}`);
}

// Concrete tools mention (warn)
const toolSignals = ["n8n","google sheets","deepseek","canva","drive"];
const toolHits = toolSignals.filter(t => lower(html).includes(t));
if (toolHits.length < 2) warnings.push("Consider mentioning at least 2 concrete tools (n8n/Sheets/DeepSeek/Canva/Drive)");

// ------------------ Banned phrases check ------------------
const allText = lower(JSON.stringify(b));
banned.forEach(p => {
  if (p && allText.includes(lower(p))) {
    //errors.push(`Contains banned phrase: "${p}"`);
  }
});

// ------------------ Hero prompt checks ------------------
const hero = lower(b.hero_prompt);
if (hero.includes("midjourney") || hero.includes("--ar") || hero.includes("--v")) {
  errors.push("hero_prompt must not include Midjourney params or jargon");
}
if (!hero.includes("minimal")) warnings.push("hero_prompt: consider explicitly stating 'minimal'");
//if (hero.includes("gradient")) errors.push("hero_prompt should avoid gradients (spec says no gradients)");

// ------------------ PLAN alignment checks (soft) ------------------
const coreTopic = safe(plan["Core Topic"] || plan.CoreTopic || plan.core_topic || "");
if (coreTopic && !lower(b.title).includes(lower(coreTopic.split(":")[0].trim()))) {
  warnings.push("Title may not clearly align with PLAN core topic (soft check)");
}

// ------------------ Final ------------------
if (errors.length) {
  throw new Error("Blog validation failed:\n- " + errors.join("\n- "));
}

return [{
  json: {
    blog: b,
    blog_validation: {
      status: "passed",
      warnings,
      approx_word_count: wordCount,
      h2Count,
      h3Count,
      codeBlocks
    }
  }
}];

// Presence Validator (Code)
// Expected input: { planRow, pkg } from Collector/Normalizer
// Output: same payload + presence_validation

const safeObj = (v) => (v && typeof v === "object" ? v : {});
const safeStr = (v) => (typeof v === "string" ? v : "");
const safeArr = (v) => (Array.isArray(v) ? v : []);

const planRow = safeObj($json.planRow);
const pkg = safeObj($json.pkg);
const outputs = safeObj(pkg.outputs);

const errors = [];
const warnings = [];
const missing = [];
const present = [];

const isNonEmptyString = (v) => safeStr(v).trim().length > 0;
const isNonEmptyArray = (v) => Array.isArray(v) && v.length > 0;
const isNonEmptyObject = (v) => v && typeof v === "object" && Object.keys(v).length > 0;

// Path helpers
const get = (obj, path) => {
  try {
    return path.split(".").reduce((o, k) => (o ? o[k] : undefined), obj);
  } catch {
    return undefined;
  }
};

const req = (path, type = "string", level = "error") => {
  const val = get(outputs, path);

  let ok = false;
  if (type === "string") ok = isNonEmptyString(val);
  else if (type === "array") ok = isNonEmptyArray(val);
  else if (type === "object") ok = isNonEmptyObject(val);
  else ok = val !== undefined && val !== null;

  if (ok) {
    present.push(path);
  } else {
    missing.push(path);
    const msg = `Missing/empty required: outputs.${path}`;
    if (level === "warning") warnings.push(msg);
    else errors.push(msg);
  }
};

// -------------------
// REQUIRED BY CHANNEL
// -------------------

// Blogger
req("blogger.title");
req("blogger.slug");
req("blogger.meta_description");
req("blogger.html");
req("blogger.hero_prompt");
req("blogger.keywords", "array", "warning"); // allow warning, sometimes empty

// YouTube short + long (these may be optional depending on your run)
req("youtube.short.hook", "string", "warning");
req("youtube.short.title", "string", "warning");
req("youtube.short.script_en", "string", "warning");
req("youtube.long.title", "string", "warning");
req("youtube.long.hook", "string", "warning");
req("youtube.long.script_en", "string", "warning");
req("youtube.long.script_hi", "string", "warning");

// Instagram
req("instagram.reel.hook", "string", "warning");
req("instagram.reel.caption", "string", "warning");
req("instagram.post.caption", "string", "warning");
req("instagram.carousel.cover", "string", "warning");
req("instagram.carousel.slides", "array", "warning");

// Facebook
req("facebook.post", "string", "warning");

// LinkedIn
// NOTE: in your normalizer: linkedin.post is a string, linkedin.article is object
req("linkedin.post", "string", "warning");
req("linkedin.article.title", "string", "warning");
req("linkedin.article.body", "string", "warning");
req("linkedin.article.cta", "string", "warning");

// Pinterest
req("pinterest.title", "string", "warning");
req("pinterest.description", "string", "warning");
req("pinterest.board", "string", "warning");
req("pinterest.image_prompt", "string", "warning");

// X
req("x.thread", "array", "warning");
req("x.tweet", "string", "warning");

// Reddit
req("reddit.title", "string", "warning");
req("reddit.post_body", "string", "warning");
req("reddit.tldr", "string", "warning");

// -------------------
// EXTRA QUALITY CHECKS
// -------------------

// Carousel slides exactly 8 (warning)
const slides = get(outputs, "instagram.carousel.slides");
if (Array.isArray(slides) && slides.length !== 8) {
  warnings.push(`Instagram carousel slides should be 8, found ${slides.length}`);
}

// Blog HTML should contain <article> (warning)
const blogHtml = safeStr(get(outputs, "blogger.html"));
if (blogHtml && !blogHtml.includes("<article")) {
  warnings.push("Blogger HTML does not include <article> wrapper.");
}

// Meta: day/core topic sanity (warning)
if (!planRow || Object.keys(planRow).length === 0) {
  warnings.push("planRow is empty/missing.");
}
if (!isNonEmptyString(get(pkg, "meta.core_topic"))) {
  warnings.push("pkg.meta.core_topic is empty.");
}

// -------------------
// SUMMARY + RETURN
// -------------------
const status = errors.length ? "failed" : "passed";

const presence_validation = {
  status,
  errors,
  warnings,
  missing,
  present,
  coverage: {
    present_count: present.length,
    missing_count: missing.length,
    error_count: errors.length,
    warning_count: warnings.length
  }
};

return [
  {
    json: {
      ...$json,
      presence_validation
    }
  }
];

