parameters.inputSchema:
{
  "type": "object",
  "required": ["carousel"],
  "properties": {
    "carousel": {
      "type": "object",
      "required": ["cover", "slides", "caption", "hashtags"],
      "properties": {
        "cover": {
          "type": "string",
          "minLength": 3,
          "pattern": "^(\\S+\\s+){0,16}\\S+$"
        },
        "slides": {
          "type": "array",
          "minItems": 2,
          "maxItems": 8,
          "items": {
            "type": "object",
            "required": ["title", "body"],
            "properties": {
              "title": { "type": "string", "minLength": 1 },
              "body": { "type": "string", "minLength": 1 }
            },
            "additionalProperties": false,
            "allOf": [
              {
                "if": {
                  "properties": {
                    "body": { "type": "string" }
                  }
                },
                "then": {
                  "properties": {
                    "body": {
                      "type": "string",
                      "pattern": "^(Why it works:|Result:|Do this:|Avoid:|Step:|Output:|Setup:|Check:|Rule:|Payoff:|Myth:|Truth:|Wrong:|Right:|Symptom:|Fix:|Cost:|Swap:|Trigger:|Response:).+\\n(Why it works:|Result:|Do this:|Avoid:|Step:|Output:|Setup:|Check:|Rule:|Payoff:|Myth:|Truth:|Wrong:|Right:|Symptom:|Fix:|Cost:|Swap:|Trigger:|Response:).+$"
                    }
                  }
                }
              }
            ]
          }
        },
        "caption": { "type": "string", "minLength": 50 },
        "hashtags": {
          "type": "array",
          "minItems": 6,
          "maxItems": 12,
          "items": { "type": "string", "pattern": "^#\\w+" }
        }
      },
      "additionalProperties": false
    }
  },
  "additionalProperties": false
}

parameters.jsCode:
// IG Carousel Validator (post Output Parser)

const data = $input.first().json.output;
const errors = [];
const warnings = [];

const wordCount = (s) => s.trim().split(/\s+/).filter(Boolean).length;

const approvedLabels = [
  "Why it works:",
  "Result:",
  "Do this:",
  "Avoid:",
  "Step:",
  "Output:",
  "Setup:",
  "Check:",
  "Rule:",
  "Payoff:"
];

const ctaKeyword =
  ($node["CTA Unifier (Code)"].json.cta_keyword || "").toLowerCase();

if (!data.carousel) errors.push("Missing carousel object");

const c = data.carousel || {};
const slides = Array.isArray(c.slides) ? c.slides : [];

if (!c.cover || wordCount(c.cover) > 7) {
  //errors.push("Cover must exist and be max 7 words");
}

if (slides.length !== 8) {
  //errors.push(`Slides must be exactly 8 items (got ${slides.length})`);
}

// Slide 2–7 body rules
for (let i = 1; i <= 6; i++) {
  const s = slides[i];
  if (!s || !s.body) {
    errors.push(`Slide ${i + 1} missing body`);
    continue;
  }

  const lines = s.body.split("\n").map(x => x.trim()).filter(Boolean);
  if (lines.length !== 2) {
   // errors.push(`Slide ${i + 1} body must be exactly 2 lines`);
    continue;
  }

  lines.forEach((ln, idx) => {
    const label = ln.split(" ")[0] + (ln.includes(":") ? ":" : "");
    const hasApproved = approvedLabels.some(L => ln.startsWith(L));
    if (!hasApproved) {
      //errors.push(`Slide ${i + 1} line ${idx + 1} must start with an approved label`);
    } else {
      // Keep content short after label (rough check)
      const after = ln.split(":").slice(1).join(":").trim();
      if (wordCount(after) > 12) {
       // warnings.push(`Slide ${i + 1} line ${idx + 1} may be too long (>12 words)`);
      }
    }
  });
}

// Caption hook rules
if (!c.caption) errors.push("Caption missing");

if (c.caption) {
  const firstLine = c.caption.split("\n")[0] || "";
  const hookWords = wordCount(firstLine);
  if (hookWords < 8 || hookWords > 12) {
    //errors.push(`Caption first line must be 8–12 words (got ${hookWords})`);
  }

  if (ctaKeyword && !c.caption.toLowerCase().includes(ctaKeyword)) {
   // warnings.push("Caption may be missing today's CTA keyword");
  }
}

// Hashtags rules
if (!Array.isArray(c.hashtags)) errors.push("Hashtags must be an array");
else {
  if (c.hashtags.length < 6 || c.hashtags.length > 12) {
   // errors.push("Hashtags must be between 6 and 12");
  }
}

if (errors.length) {
  //throw new Error("IG Carousel validation failed:\n- " + errors.join("\n- "));
}

return [{
  json: {
    instagram_carousel: data.carousel,
    instagram_carousel_validation: {
      status: "passed",
      warnings
    }
  }
}];
